#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>

// Reads one '\n'-terminated line into buf (without the '\n').
// Returns its length, or -1 if the other side hung up first.
int recv_line(int fd, char *buf, int room) {
    int len = 0;
    char c;
    while (recv(fd, &c, 1, 0) == 1) {
        if (c == '\n') {
            buf[len] = '\0';
            return len;
        }
        if (len < room - 1) buf[len++] = c;
    }
    return -1;
}

// The beacon: answer each command line with one reply line.
void serve(int fd) {
    char line[128], reply[64];
    long long value = 0;
    while (recv_line(fd, line, sizeof line) >= 0) {
        char cmd[16];
        long long x = 0;
        int got = sscanf(line, "%15s %lld", cmd, &x);
        int is_math = got == 2 && (strcmp(cmd, "SET") == 0 || strcmp(cmd, "ADD") == 0 || strcmp(cmd, "SUB") == 0 ||
                                   strcmp(cmd, "MUL") == 0 || strcmp(cmd, "DIV") == 0);
        if (got == 1 && strcmp(cmd, "QUIT") == 0) {
            send(fd, "BYE\n", 4, 0);
            return;
        }
        if (got == 1 && strcmp(cmd, "GET") == 0) {
            snprintf(reply, sizeof reply, "= %lld\n", value);
        } else if (!is_math) {
            snprintf(reply, sizeof reply, "ERR unknown command\n");
        } else if (strcmp(cmd, "DIV") == 0 && x == 0) {
            snprintf(reply, sizeof reply, "ERR divide by zero\n");
        } else {
            if (strcmp(cmd, "SET") == 0) value = x;
            else if (strcmp(cmd, "ADD") == 0) value += x;
            else if (strcmp(cmd, "SUB") == 0) value -= x;
            else if (strcmp(cmd, "MUL") == 0) value *= x;
            else value /= x;
            snprintf(reply, sizeof reply, "= %lld\n", value);
        }
        send(fd, reply, strlen(reply), 0);
    }
}

int main(void) {
    int fds[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == -1) {
        perror("socketpair");
        return 1;
    }
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {
        close(fds[0]);
        serve(fds[1]);
        close(fds[1]);
        _exit(0);
    }
    close(fds[1]);

    char line[128], reply[128];
    while (fgets(line, sizeof line, stdin) != NULL) {
        // MSG_NOSIGNAL: if the beacon has hung up, fail quietly instead of being killed by SIGPIPE.
        send(fds[0], line, strlen(line), MSG_NOSIGNAL);
        if (recv_line(fds[0], reply, sizeof reply) < 0) {
            printf("(beacon offline)\n");
            break;
        }
        printf("%s\n", reply);
    }
    close(fds[0]);
    waitpid(pid, NULL, 0);
    return 0;
}
